prts.feedbackvariables:
stuclass:[classification1,classification2,classification3,classification4];

newans:addcol(
  ans1,
  matrix([classification1],[classification2],[classification3],[classification4])
);

studentpoints:[];
studentrows:[];

nothing:if true then
  (for i:1 thru 4 do
    if not zeromatrixp(row(newans,i)) then
      (
        studentpoints:endcons([ans1[i][1],ans1[i][2]],studentpoints),
        studentrows:endcons([ans1[i][1],ans1[i][2],stuclass[i]],studentrows)
      )
  );

nentered:length(studentpoints);

countok:if nentered=l then 1 else 0;

p1ok:if member(extract[1],studentpoints) then 1 else 0;
p2ok:if member(extract[2],studentpoints) then 1 else 0;

c1ok:if member(class[1],studentrows) then 1 else 0;
c2ok:if member(class[2],studentrows) then 1 else 0;

npoints:p1ok+p2ok;
nclasses:c1ok+c2ok;
earned:countok+npoints+nclasses;
